mapper.select:
SELECT
    r.id, r.recharge_no, r.member_id, m.real_name as member_name,
    r.recharge_amount, r.bonus_amount, r.total_amount,
    r.balance_before, r.balance_after, r.payment_method, r.status,
    r.paid_at, r.created_at
FROM member_recharge r
LEFT JOIN member m ON r.member_id = m.id
WHERE r.deleted_at IS NULL

    AND r.member_id = #{memberId}


    AND r.created_at >= #{startTime}


    AND r.created_at <= #{endTime}


    AND r.status = #{status}

ORDER BY r.created_at DESC
